'use strict';
const $=s=>document.querySelector(s),fmt=n=>new Intl.NumberFormat('en').format(n),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let districts,living,mobility,selectedYear=2023;
const catalogue='https://www.pnd.gog.pk/pages/downloads';
const sources=[{title:'GB Statistical Year Book 2024',url:catalogue,type:'OFFICIAL COMPILATION',text:'Population: tables 3.2–3.14, PDF pages 81–86. Literacy: table 3.9, PDF page 85. Supplied PDF inspected; link opens the publisher’s catalogue.'},{title:'AJ&K Statistical Year Book 2024',url:'https://www.pndajk.gov.pk/uploadfiles/downloads/AJ%26K%20Statistical%20Year%20Book%202024%281%29.pdf',type:'OFFICIAL HISTORICAL COMPILATION',text:'GB historical benchmarks, table 15.20, PDF page 211 / printed page 176. Early values are rounded, not exact headcounts.'},{title:'GB MICS 2024–25 · Survey Findings Report',url:catalogue,type:'HOUSEHOLD SURVEY',text:'Living conditions: LN.6.1, WS.1.2, WS.3.7. Title dated December 2025. Supplied full report inspected; catalogue link is not a direct PDF.'},{title:'UNICEF · GB MICS 2016–17',url:'https://www.unicef.org/pakistan/reports/multiple-indicator-cluster-survey-2016-17-report-and-key-findings-gilgit-baltistan',type:'HOUSEHOLD SURVEY',text:'Earlier household and fertility indicators. Compare definitions and reference periods before drawing trends.'},{title:'GB at a Glance 2020',url:'https://portal.pnd.gog.pk/Content/Files/Reports/Gilgit%20Baltistan%20at%20a%20Glance%20New%20Design%202020%20Final_210554160.pdf',type:'INDEXED EVIDENCE · RETRIEVAL FAILED',text:'Competing 1951 population of approximately 252,000. Indexed text inspected; original file not fully audited.'},{title:'Unlocking Investment Opportunities in GB',url:catalogue,type:'POLICY / INVESTMENT REPORT',text:'Rounded 1.7 million refers to a 2022 estimate, not an additional census. Supplied PDF pages 59 and 74.'}];
function benchmarks(){return [{year:1951,pop:+$('#early').value,status:'Disputed, rounded benchmark',note:$('#early').value==='254000'?'Yearbook table 3.13, PDF 86; AJ&K table 15.20, PDF 211. Competing version: 252,000.':'GB at a Glance 2020 indexed text; direct retrieval failed. Competing inspected version: 254,000.',disputed:true},{year:1961,pop:308000,status:'Rounded benchmark; source error flagged',note:'AJ&K table 15.20, PDF 211 supports 308,000. GB yearbook prints “8” thousand in table 3.13.',disputed:true},{year:1972,pop:417000,status:'Rounded historical benchmark',note:'GB yearbook table 3.13; AJ&K table 15.20.'},{year:1981,pop:575000,status:'Rounded historical benchmark',note:'GB yearbook table 3.13; AJ&K table 15.20.'},{year:1998,pop:884000,status:'Rounded historical benchmark',note:'GB yearbook table 3.13; AJ&K table 15.20.'},{year:2017,pop:$('#version').value==='A'?1492924:1492685,status:'Disputed source version',note:$('#version').value==='A'?'GB yearbook table 3.3, PDF 82. Alternative: 1,492,685.':'GB yearbook tables 3.2 / 3.7, PDF 81 / 84. Alternative: 1,492,924.',disputed:true},...($('#estimate').checked?[{year:2022,pop:1700000,status:'Rounded estimate, not census',note:'Investment report, PDF 59 / 74. Explicitly a 2022 estimate.',estimate:true}]:[]),{year:2023,pop:1709049,status:'Census total reported in yearbook',note:'GB yearbook table 3.3(a), PDF 82 / printed 60. Underlying original census volume not independently obtained.'}];}
function pointDetail(d){$('#point-detail').innerHTML=`<strong>${d.year} · ${fmt(d.pop)} people</strong> <span> / ${d.status}</span><br>${d.note} <a href="#sources">Source register ↗</a>`;}
function renderPopulation(){const rows=benchmarks(),x=y=>65+(y-1951)/74*890,y=v=>315-v/2000000*265;let s='<svg viewBox="0 0 1020 380" role="img" aria-label="Population benchmarks from 1951 to 2023. 2025 is missing.">';for(let v=0;v<=2000000;v+=500000)s+=`<line x1="65" x2="955" y1="${y(v)}" y2="${y(v)}" stroke="#e1e5d9"/><text x="53" y="${y(v)+4}" text-anchor="end" font-size="11" fill="#667568">${v/1000000}m</text>`;s+='<text x="65" y="24" font-size="10" fill="#667568">POPULATION · PERSONS</text>';rows.forEach(d=>{const color=d.disputed?'#a66426':'#245a49';s+=`<g class="point" tabindex="0" role="button" aria-label="${d.year}, ${fmt(d.pop)}, ${d.status}" data-year="${d.year}"><title>${d.year}: ${fmt(d.pop)} · ${d.status}</title><line x1="${x(d.year)}" x2="${x(d.year)}" y1="${y(d.pop)}" y2="315" stroke="#dae1d4" stroke-dasharray="3 5"/><circle cx="${x(d.year)}" cy="${y(d.pop)}" r="${d.year===selectedYear?9:6}" fill="${d.estimate?'#fffef9':color}" stroke="${color}" stroke-width="2"/><text x="${x(d.year)}" y="${d.year===2022?353:337}" text-anchor="middle" font-size="11" fill="#53665a">${d.year}</text></g>`;});s+=`<line x1="955" x2="955" y1="55" y2="315" stroke="#959c8f" stroke-dasharray="4 5"/><text x="955" y="45" text-anchor="middle" font-size="10" fill="#757a70">No count</text><text x="955" y="372" text-anchor="middle" font-size="11" fill="#757a70">2025</text></svg>`;$('#population-chart').innerHTML=s;$('#population-chart').querySelectorAll('.point').forEach(el=>{const activate=()=>{selectedYear=+el.dataset.year;renderPopulation();};el.addEventListener('click',activate);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate();}});});pointDetail(rows.find(r=>r.year===selectedYear)||rows.at(-1));$('#population-table').innerHTML=`<table><thead><tr><th>Year</th><th>Population</th><th>Status / source</th></tr></thead><tbody>${rows.map(d=>`<tr><td>${d.year}</td><td>${fmt(d.pop)}</td><td>${d.status}. ${d.note}</td></tr>`).join('')}<tr><td>2025</td><td>Not verified</td><td>Missing observed total. Not zero.</td></tr></tbody></table>`;}
function renderDistricts(){if(!districts)return;const names=$('#district-mode').value==='all'?[...new Set(districts.rows.map(r=>r.geography))]:[...new Set([$('#district-one').value,$('#district-two').value])],rows=names.map(n=>({name:n,old:districts.rows.find(r=>r.geography===n&&r.version===$('#version').value),now:districts.rows.find(r=>r.geography===n&&r.year===2023)})),max=350000;$('#district-chart').innerHTML=rows.map(r=>`<div class="district-row"><div class="district-name">${r.name}</div><div class="bar-pair"><div class="bar old" style="width:${r.old.population/max*100}%"><span>${fmt(r.old.population)}</span></div><div class="bar" style="width:${r.now.population/max*100}%"><span>${fmt(r.now.population)}</span></div></div></div>`).join('');$('#district-detail').innerHTML=`<b>${rows.length} reporting districts · 2017 source version ${$('#version').value}</b><br><span>All bars use the same 0–350,000 scale. 2023: yearbook table 3.3(a), PDF page 82. Change does not isolate births, deaths or migration.</span>`;$('#district-table').innerHTML=`<table><thead><tr><th>District</th><th>2017</th><th>2023</th><th>Arithmetic difference</th><th>2017 table / PDF page</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.name}</td><td>${fmt(r.old.population)}</td><td>${fmt(r.now.population)}</td><td>${fmt(r.now.population-r.old.population)}</td><td>${r.old.table} / ${r.old.pdf_page}</td></tr>`).join('')}</tbody></table>`;}
const sourceLine=s=>`<a href="${s.url}" target="_blank" rel="noopener">${s.document} · ${s.table} ↗</a><small>PDF p. ${s.pdfPage} / printed p. ${s.printedPage}. Link: publisher catalogue.</small>`;
function renderLiving(topic){const box=$('#living-content');if(topic==='literacy'){const l=living.literacy;box.innerHTML=`<div class="toolbar"><label>2017 residence group<select id="literacy-area">${l.rows.map(r=>`<option>${r.area}</option>`).join('')}</select></label><p class="caption">Population aged 10+ · Census 2017, reproduced in the 2024 yearbook.<br>No validated recent district literacy series is available in this review.</p></div><div id="literacy-cards" class="indicator-grid" style="margin-top:20px"></div><div class="note"><p><b>Literacy and reading assessments are different measures.</b>The 2024–25 MICS estimate of foundational reading among children aged 7–14 is 26.2%. That is not comparable to literacy among all people aged 10+. The test was unavailable in the home/instruction language for 27.6% of children; some could opt for available languages. MICS LN.4.1, PDF p. 227.</p></div>`;const draw=()=>{const r=l.rows.find(r=>r.area===$('#literacy-area').value);$('#literacy-cards').innerHTML=[['All people',r.total],['Male',r.male],['Female',r.female]].map(([t,v])=>`<article class="indicator"><h3>${t} · ${r.area}</h3><div class="value">${v.toFixed(2)}%</div><div class="unit">Literacy, ages 10+ · 2017</div><p>Within-group percentage; not a 2025 estimate.</p>${sourceLine(l.source)}</article>`).join('');};$('#literacy-area').addEventListener('change',draw);draw();}else if(topic==='households'){box.innerHTML=`<div class="indicator-grid"><article class="indicator"><h3>Average household size</h3><div class="pair"><div class="value">7.7<small>2016–17</small></div><div>→</div><div class="value">6.7<small>2024–25</small></div></div><p>People per household. Smaller households can coexist with a growing population; residence definitions still need harmonization.</p><a href="#sources">MICS · earlier PDF p. 7 / newer p. 58 ↗</a></article><article class="indicator"><h3>Total fertility rate</h3><div class="pair"><div class="value">4.6<small>2016–17 survey</small></div><div>→</div><div class="value">4.2<small>2024–25 survey</small></div></div><p>Children per woman. Earlier estimate uses one preceding year; newer estimate uses three. Difference is not a demonstrated annual trend.</p><a href="#sources">MICS · RH.2 / TM.1.1 ↗</a></article><article class="indicator"><h3>Uncertainty belongs in the story</h3><div class="value">3.88–4.56</div><div class="unit">Newer fertility estimate · reported confidence interval</div><p>A formal change test also needs older uncertainty and comparable reference periods. New full report Appendix C, SE.1, PDF p. 349.</p><a href="#sources">Read the survey documentation ↗</a></article></div>`;}else{box.innerHTML=`<div class="toolbar"><label>Compare living conditions<select id="services-scope"><option value="residence">Urban and rural</option><option value="wealth">Poorest and richest asset quintiles</option>${living.districtProfiles.map(r=>`<option value="${r.district}">${r.district} and GB overall</option>`).join('')}</select></label></div><div id="service-cards" class="indicator-grid" style="margin-top:20px"></div><p class="caution">Survey point estimates, not performance rankings. Differences have not been significance-tested. Basic water does not establish contamination-free water; basic sanitation is not safely managed sanitation. Wealth groups are asset quintiles, not income bands.</p>`;const draw=()=>{const scope=$('#services-scope').value;$('#service-cards').innerHTML=living.livingIndicators.map(d=>{let a,b,al,bl;if(scope==='residence'){a=d.urban;b=d.rural;al='Urban';bl='Rural';}else if(scope==='wealth'){a=d.poorestQuintile;b=d.richestQuintile;al='Poorest quintile';bl='Richest quintile';}else{a=living.districtProfiles.find(r=>r.district===scope)[d.id];b=d.total;al=scope;bl='GB overall';}return `<article class="indicator"><h3>${d.title}</h3><div class="pair"><div class="value">${a.toFixed(1)}%<small>${al}</small></div><div class="value">${b.toFixed(1)}%<small>${bl}</small></div></div><p>${d.definition}. Denominator: <b>${d.denominator}</b>. Survey 2024–25.</p>${sourceLine(d.source)}</article>`;}).join('');};$('#services-scope').addEventListener('change',draw);draw();}}
function renderMobility(topic){let ids=topic==='climate'?['climate-hazards','climate-relocation','glacier-variation']:topic==='youth'?['education-mobility','youth-destinations','mobility-inequality']:['urban-living','land-pressure'];$('#mobility-content').innerHTML=ids.map(id=>{const d=mobility.entries.find(r=>r.id===id);return `<article class="evidence-block"><h3>${d.title}</h3><p>${d.text}</p><a href="${d.url}" target="_blank" rel="noopener">${d.source_title} ↗</a><p class="caption">${d.evidence_status} · ${d.scope}</p></article>`;}).join('')+(topic==='comparison'?'<div class="note"><p><b>GB versus another city or country?</b>No matched dataset on living costs, wages, housing, education and health has been validated here. The living-conditions explorer compares areas within GB. Overseas “better life” rankings would need consistent years, purchasing power, and migration status.</p></div>':'');}
function renderSources(){const q=$('#source-search').value.toLowerCase(),list=sources.filter(d=>(d.title+' '+d.text+' '+d.type).toLowerCase().includes(q));$('#source-list').innerHTML=list.length?list.map(d=>`<article class="source"><small>${esc(d.type)}</small><br><a href="${d.url}" target="_blank" rel="noopener">${esc(d.title)} ↗</a><p>${esc(d.text)}</p></article>`).join(''):'<p>No matching sources. Try climate, population, literacy or migration.</p>';}
async function init(){try{[districts,living,mobility]=await Promise.all(['districts','living-data','climate-migration'].map(async n=>{const r=await fetch(`assets/${n}.json`);if(!r.ok)throw Error('Data unavailable');return r.json();}));const names=[...new Set(districts.rows.map(r=>r.geography))];['#district-one','#district-two'].forEach(id=>{$(id).innerHTML=names.map(n=>`<option>${n}</option>`).join('');});$('#district-one').value='Gilgit';$('#district-two').value='Skardu';sources.push(...mobility.entries.map(d=>({title:d.source_title,url:d.url,type:d.evidence_status.toUpperCase(),text:d.text+' Scope: '+d.scope})));renderPopulation();renderDistricts();renderLiving('literacy');renderMobility('climate');renderSources();$('#version').addEventListener('change',()=>{renderPopulation();renderDistricts();});['#early','#estimate'].forEach(id=>$(id).addEventListener('change',renderPopulation));['#district-one','#district-two','#district-mode'].forEach(id=>$(id).addEventListener('change',renderDistricts));document.querySelectorAll('[data-life]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-life]').forEach(e=>{e.classList.toggle('active',e===b);e.setAttribute('aria-pressed',e===b);});renderLiving(b.dataset.life);}));document.querySelectorAll('[data-mobility]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-mobility]').forEach(e=>{e.classList.toggle('active',e===b);e.setAttribute('aria-pressed',e===b);});renderMobility(b.dataset.mobility);}));$('#source-search').addEventListener('input',renderSources);}catch(e){$('#population-chart').innerHTML='<p>Interactive data could not load. Please reload, or use the downloadable research and source ledgers below.</p>';console.error(e);}}
init();
